/**
 * The overview screen (`design/archetypes/dashboard.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/dashboard.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { Each, claimSlot, resolveSlot, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/archetypes/dashboard.module.css'
import Card from '../structure/Card'
import PageHeader from '../structure/PageHeader'
import Stat, { type StatProps } from '../structure/Stat'

export interface DashboardProps {
  /**
   * Header actions, which most dashboards do not have because they only display data.
   */
  actions?: JSX.Element
  description?: string
  /**
   * The main column.
   */
  primary: JSX.Element
  /**
   * The narrow column. Omit and `primary` spans the full width.
   */
  secondary?: JSX.Element
  /**
   * Two to four stats, because more than four belong in a table.
   */
  stats?: StatProps[]
  title: string
  /**
   * PageHeader's: an InlineEdit of the title, for an overview of one thing the reader names,
   * such as an environment.
   */
  titleEdit?: JSX.Element
}

/** The overview screen. */
export default function Dashboard(given: DashboardProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const actionsSlot = resolveSlot(() => props.actions)
    const secondarySlot = resolveSlot(() => props.secondary)
    const titleEditSlot = resolveSlot(
      () => props.titleEdit,
      () => ({ valueHidden: true }),
    )
    return (
      <div class={styles.page} data-member="dashboard">
        <PageHeader
          title={props.title}
          description={props.description}
          titleEdit={titleEditSlot.filled() ? titleEditSlot() : undefined}
          actions={actionsSlot.filled() ? actionsSlot() : undefined}
        />
        {props.stats !== undefined && props.stats.length > 0 ? (
          <div class={styles.stats} data-count={String(props.stats.length)}>
            <Each of={props.stats} by={(stat, at) => `${at}-${stat.label}`} renew>
              {(stat) => (
                <Card>
                  <Stat
                    label={stat.label}
                    value={stat.value}
                    numeric={stat.numeric}
                    icon={stat.icon}
                    delta={stat.delta}
                    deltaLabel={stat.deltaLabel}
                    trend={stat.trend}
                    spark={stat.spark}
                    sparkLabel={stat.sparkLabel}
                    description={stat.description}
                    footer={stat.footer}
                    loading={stat.loading}
                    loadingLabel={stat.loadingLabel}
                  />
                </Card>
              )}
            </Each>
          </div>
        ) : null}
        {/* body */}
        <div class={styles.body} data-secondary={secondarySlot.filled() ? '' : undefined}>
          {/* primary */}
          <div class={styles.primary}>{props.primary}</div>
          {secondarySlot.filled() ? <div class={styles.secondary}>{secondarySlot()}</div> : null}
        </div>
      </div>
    )
  })
}
